// Integration tests for SVG to PNG Worker
// Run with: npm test

const WORKER_URL = process.env.WORKER_URL || "http://127.0.0.1:8787";

const tests = [
  {
    name: "Wikipedia Logo (512px width)",
    url: `${WORKER_URL}/https://upload.wikimedia.org/wikipedia/commons/8/80/Wikipedia-logo-v2.svg`,
    expectStatus: 200,
    expectContentType: "image/png",
    validateBody: async (response: Response) => {
      const buffer = await response.arrayBuffer();
      const bytes = new Uint8Array(buffer);
      // Check PNG signature
      const pngSignature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
      for (let i = 0; i < 8; i++) {
        if (bytes[i] !== pngSignature[i]) return "Invalid PNG signature";
      }
      // Check size is reasonable (> 1KB)
      if (buffer.byteLength < 1000) return "PNG too small";
      return null;
    }
  },
  {
    name: "Font Awesome Heart Icon",
    url: `${WORKER_URL}/https://raw.githubusercontent.com/FortAwesome/Font-Awesome/6.x/svgs/solid/heart.svg`,
    expectStatus: 200,
    expectContentType: "image/png",
    validateBody: async (response: Response) => {
      const buffer = await response.arrayBuffer();
      const bytes = new Uint8Array(buffer);
      const pngSignature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
      for (let i = 0; i < 8; i++) {
        if (bytes[i] !== pngSignature[i]) return "Invalid PNG signature";
      }
      return null;
    }
  },
  {
    name: "Invalid URL - no protocol",
    url: `${WORKER_URL}/example.com/test.svg`,
    expectStatus: 400,
    expectContentType: "application/json",
  },
  {
    name: "Invalid URL - FTP protocol",
    url: `${WORKER_URL}/ftp://example.com/test.svg`,
    expectStatus: 400,
    expectContentType: "application/json",
  },
];

async function runTests() {
  console.log(`Testing against: ${WORKER_URL}\n`);
  let passed = 0;
  let failed = 0;

  for (const test of tests) {
    try {
      const response = await fetch(test.url);

      // Check status
      if (response.status !== test.expectStatus) {
        console.log(`✗ ${test.name}: Expected status ${test.expectStatus}, got ${response.status}`);
        failed++;
        continue;
      }

      // Check content type
      const contentType = response.headers.get("content-type") || "";
      if (!contentType.includes(test.expectContentType)) {
        console.log(`✗ ${test.name}: Expected Content-Type ${test.expectContentType}, got ${contentType}`);
        failed++;
        continue;
      }

      // Validate body if validator provided
      if (test.validateBody) {
        const error = await test.validateBody(response);
        if (error) {
          console.log(`✗ ${test.name}: ${error}`);
          failed++;
          continue;
        }
      }

      console.log(`✓ ${test.name}`);
      passed++;
    } catch (error) {
      console.log(`✗ ${test.name}: ${error instanceof Error ? error.message : String(error)}`);
      failed++;
    }
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

runTests();

