import { Resvg, initWasm } from "@resvg/resvg-wasm";
// 直接导入 WASM 文件 - wrangler 会将其作为 WebAssembly.Module 处理
import wasmModule from "../node_modules/@resvg/resvg-wasm/index_bg.wasm";

// 全局变量，确保只初始化一次
let wasmInitialized = false;

async function ensureWasmInitialized() {
  if (!wasmInitialized) {
    // wasmModule 应该是一个 WebAssembly.Module
    await initWasm(wasmModule as any);
    wasmInitialized = true;
  }
}

export interface Env {
  // 环境变量（如果有需要）
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    // 从路径中提取 SVG URL
    // 格式: /https://example.com/image.svg
    let svgUrl = url.pathname.slice(1);

    // 如果路径以 http 开头，处理可能的重复编码
    if (svgUrl.startsWith("http://") || svgUrl.startsWith("https://")) {
      // 直接提取 URL
    } else if (url.pathname.startsWith("//")) {
      // 处理 //example.com/path 格式
      svgUrl = "https:" + url.pathname;
    } else {
      return new Response(
        JSON.stringify({ error: "Invalid URL format. Use: /https://example.com/image.svg" }),
        { status: 400, headers: { "Content-Type": "application/json" } }
      );
    }

    // 解码 URL
    try {
      svgUrl = decodeURIComponent(svgUrl);
    } catch (e) {
      // 如果解码失败，使用原始 URL
    }

    // 验证 URL
    let targetUrl: URL;
    try {
      targetUrl = new URL(svgUrl);
    } catch (e) {
      return new Response(
        JSON.stringify({ error: "Invalid SVG URL" }),
        { status: 400, headers: { "Content-Type": "application/json" } }
      );
    }

    // 只允许 http 和 https 协议
    if (targetUrl.protocol !== "http:" && targetUrl.protocol !== "https:") {
      return new Response(
        JSON.stringify({ error: "Only HTTP and HTTPS protocols are supported" }),
        { status: 400, headers: { "Content-Type": "application/json" } }
      );
    }

    try {
      // 下载 SVG
      const svgResponse = await fetch(svgUrl, {
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; SVG2PNG-Worker/1.0)",
        },
      });

      if (!svgResponse.ok) {
        return new Response(
          JSON.stringify({ error: `Failed to fetch SVG: ${svgResponse.status} ${svgResponse.statusText}` }),
          { status: 502, headers: { "Content-Type": "application/json" } }
        );
      }

      // 获取 SVG 文本
      const svgText = await svgResponse.text();

      if (!svgText.includes("<svg") && !svgText.includes("<?xml")) {
        return new Response(
          JSON.stringify({ error: "The URL does not appear to point to a valid SVG file" }),
          { status: 400, headers: { "Content-Type": "application/json" } }
        );
      }

      // 初始化 WASM
      await ensureWasmInitialized();

      // 使用 resvg 将 SVG 转换为 PNG
      const resvg = new Resvg(svgText, {
        fitTo: {
          mode: "width",
          value: 512,
        },
        font: {
          loadSystemFonts: false,
        },
      });

      const pngData = resvg.render();
      const pngBuffer = pngData.asPng();

      // 返回 PNG 图片
      return new Response(pngBuffer, {
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=86400", // 缓存 24 小时
          "X-Content-Type-Options": "nosniff",
        },
      });
    } catch (error) {
      console.error("Error converting SVG to PNG:", error);
      return new Response(
        JSON.stringify({ 
          error: "Failed to convert SVG to PNG",
          details: error instanceof Error ? error.message : String(error)
        }),
        { status: 500, headers: { "Content-Type": "application/json" } }
      );
    }
  },
};
